// Generated by ORCA Test Generation Agent for SHOP-101 / SHOP-101-R1
// User can log in with valid credentials
import { test, expect } from '@playwright/test';

// Variables of the selected test environment (orca.environments.json).
const env = (name) => process.env[name] ?? '';

test.describe('SHOP-101-R1 User can log in with valid credentials', { tag: ['@regression', '@SHOP-101'] }, () => {
  test('[SHOP-101-AC1] Successful login', async ({ page, request }) => {
    // Given I am on the "login" page
    await page.goto('/login');
    // When I fill "login-email" with "demo@orca.dev"
    await page.getByTestId('login-email').fill('demo@orca.dev');
    // And I fill "login-password" with "orca123"
    await page.getByTestId('login-password').fill('orca123');
    // And I click "login-submit"
    await page.getByTestId('login-submit').click();
    // Then I should be on the "dashboard" page
    await expect(page).toHaveURL(new RegExp('/dashboard$'));
    // And "welcome-message" should show "Welcome back, Demo User"
    await expect(page.getByTestId('welcome-message')).toHaveText('Welcome back, Demo User');
  });

  test('[SHOP-101-AC2] Invalid password shows an error', async ({ page, request }) => {
    // Given I am on the "login" page
    await page.goto('/login');
    // When I fill "login-email" with "demo@orca.dev"
    await page.getByTestId('login-email').fill('demo@orca.dev');
    // And I fill "login-password" with "wrong-password"
    await page.getByTestId('login-password').fill('wrong-password');
    // And I click "login-submit"
    await page.getByTestId('login-submit').click();
    // Then I should see "Invalid email or password"
    await expect(page.getByText('Invalid email or password')).toBeVisible();
  });
});
